#!/usr/bin/env node
'use strict';
const fs=require('fs');
const path=require('path');
const crypto=require('crypto');
const root=path.resolve(__dirname,'..'),read=relative=>fs.readFileSync(path.join(root,relative),'utf8').replace(/\r\n/g,'\n'),write=(relative,value)=>fs.writeFileSync(path.join(root,relative),value);
const order=["utils.js","korean-access-data.js","korean-access-policy.js","korean-preview-access-data.js","feature-flags.js","rail-data-repository.js","asset-renderer.js","storage.js","typing.js","typing-model.js","statistics-engine.js","line-badge.js","station-sign-templates.js","transport-stop-templates.js","route-integrity.js","service-route-resolver.js","nex-route-resolver.js","famous-limited-express.js","korean-service-resolver.js","korean-research-resolver.js","track-motion.js","route-renderer.js","game.js","free-drive.js","statistics.js","network-map.js","data-loader.js","route-editor.js","auth.js","route-service-descriptions.js","app.js"];
const source=order.map(file=>read(`js/${file}`).replace(/\bimport(?=\s|\{)[^;]+;/g,'').replace(/\bexport\s+/g,'').replace(/new URL\('\.\.\/data\/([^']+)',import\.meta\.url\)/g,"new URL('./data/$1',document.baseURI)")).join('\n\n');
for(const marker of ['KR_BLOCKED_SOURCE_RELATIONS','function koreanRouteBlockReason(','function koreanRouteUnavailableReason(','function nexOperatingChoices(','function buildFamousLimitedExpressRoutes('])if(!source.includes(marker))throw new Error('Legacy bundle script omitted required module: '+marker);
const bundle=`/* AUTO-GENERATED by tools/build-app-bundle.js. DO NOT EDIT. */\n(()=>{'use strict';(async()=>{\n${source}\n})().catch(error=>{console.error('Tokyo Rail Typing failed to start:',error);const toast=document.querySelector('#toast');if(toast){toast.textContent='게임을 시작하지 못했습니다. 새로고침해 주세요.';toast.classList.add('show')}})})();\n`;
write('js/app.bundle.js',bundle);
const hash=crypto.createHash('sha256').update(bundle).digest('hex').slice(0,12),html=read('index.html').replace(/(\.\/js\/app\.bundle\.js)(?:\?v=[^"']*)?/g,`$1?v=${hash}`);const workspaceHash=crypto.createHash('sha256').update(fs.readFileSync(path.join(root,'js/line-workspace-data.js'))).digest('hex').slice(0,12);write('index.html',html.replace(/(\.\/js\/japan-lite-index\.js)(?:\?v=[^"']*)?/g,`$1?v=${crypto.createHash('sha256').update(fs.readFileSync(path.join(root,'js/japan-lite-index.js'))).digest('hex').slice(0,12)}`).replace(/(\.\/js\/line-workspace-data\.js)(?:\?v=[^"']*)?/g,`$1?v=${workspaceHash}`));
const kr=read('js/korea-index-data.js');write('index.html',read('index.html').replace(/(\.\/js\/korea-index-data\.js)(?:\?v=[^"']*)?/g,'$1?v='+crypto.createHash('sha256').update(kr).digest('hex').slice(0,12)));
write('index.html',read('index.html').replace(/(\.\/js\/result-journey-map\.js)(?:\?v=[^"']*)?/g,'$1?v='+crypto.createHash('sha256').update(read('js/result-journey-map.js')).digest('hex').slice(0,12)));
console.log(JSON.stringify({bundle:'js/app.bundle.js',hash},null,2));
